def get_HEP(task_i, task_set, policy):
    if policy == 'FP':
        return [t for t in task_set if t.id != task_i.id and t.pi >= task_i.pi]
    elif policy in ['EDF', 'FIFO']:
        return [t for t in task_set if t.id != task_i.id]

def get_HEP_plus(task_i, task_set, policy):
    return get_HEP(task_i, task_set, policy) + [task_i]

def get_B(task_i, A, task_set, policy):
    if policy == 'FP':
        return [t for t in task_set if t.pi < task_i.pi]
    elif policy == 'EDF':
        # Assuming A is relative to busy window start, so absolute deadline is A + D_i
        return [t for t in task_set if t.D > task_i.D + A]
    elif policy == 'FIFO':
        return [] # No priority inversion blocking in FIFO

def calculate_B_i_A(task_i, A, task_set, policy):
    blocking_tasks = get_B(task_i, A, task_set, policy)
    if not blocking_tasks:
        return 0
    return max(t.NPS for t in blocking_tasks) - epsilon

def calculate_IBF_i_A_delta(task_i, A, delta, task_set, policy, B_i_A_val):
    if policy == 'FP':
        interference = task_i.RBF(A + epsilon) - task_i.C + B_i_A_val
        for t_h in get_HEP(task_i, task_set, policy):
            interference += t_h.RBF(delta)
        return interference
    elif policy == 'EDF':
        interference = task_i.RBF(A + epsilon) - task_i.C + B_i_A_val
        for t_h in task_set:
            if t_h.id != task_i.id:
                interference += t_h.RBF(min(A + epsilon + task_i.D - t_h.D, delta))
        return interference
    elif policy == 'FIFO':
        interference = 0
        for t_h in task_set:
            interference += t_h.RBF(A + epsilon)
        return interference - task_i.C

def calculate_L_i(task_i, task_set, policy, B_i_0_val):
    L = 0 # Initial guess
    while True:
        demand = 0
        if policy == 'FP':
            demand += B_i_0_val
            for t_h in get_HEP_plus(task_i, task_set, policy):
                demand += t_h.RBF(L)
        elif policy in ['EDF', 'FIFO']:
            for t_h in task_set:
                demand += t_h.RBF(L)

        if demand > L:
            L = demand # Update L with new demand
        else:
            return L # Fixed point found

        # Add a safeguard for non-convergence (e.g., system overloaded)
        if L > MAX_L_THRESHOLD: # Define a reasonable upper bound
            raise Exception("System overloaded, L_i did not converge")

def calculate_B_prime_i_A_e_lp(task_i, A, e_lp, task_set, policy):
    # This definition is specifically for FP scheduling as per the paper.
    if policy != 'FP':
        raise ValueError("B_prime_i is defined for FP scheduling only in this context.")

    nominal_blocking = calculate_B_i_A(task_i, A, task_set, policy)
    return nominal_blocking + e_lp

def calculate_L_i_e(task_i, e, task_set, policy):
    L = 0 # Initial guess
    while True:
        demand = e # Total exceedance adds to demand
        if policy == 'FP':
            # For busy window length, A is typically 0, so B_i(0)
            demand += calculate_B_i_A(task_i, 0, task_set, policy)
            for t_h in get_HEP_plus(task_i, task_set, policy):
                demand += t_h.RBF(L)
        elif policy in ['EDF', 'FIFO']:
            for t_h in task_set:
                demand += t_h.RBF(L)

        if demand > L:
            L = demand
        else:
            return L

        if L > MAX_L_THRESHOLD: # Safeguard
            raise Exception("System overloaded with exceedance, L_i(e) did not converge")

def calculate_A_i_e(task_i, L_i_e, task_set, policy):
    A_i_e_set = {0}
    # Similar to calculate_A_i, this involves identifying points where IBF_i changes.
    # The key difference is the upper bound for A, which is L_i_e instead of L_i.
    # The paper states the rationale for sparse search space is unaffected by NET exceedance.
    # This implies the same underlying 'steps' of IBF_i are relevant.
    return sorted(list(A_i_e_set))

def calculate_R_i_e(task_i, e, task_set, policy):
    L_i_e_val = calculate_L_i_e(task_i, e, task_set, policy)
    A_i_e_set = calculate_A_i_e(task_i, L_i_e_val, task_set, policy)

    F_i_e_max = 0
    for A_val in A_i_e_set:
        F_A_i_e_val = calculate_F_A_i_e(task_i, A_val, e, task_set, policy)
        if F_A_i_e_val > F_i_e_max:
            F_i_e_max = F_A_i_e_val

    R_i_e_val = F_i_e_max + (task_i.C - task_i.RCT)
    return R_i_e_val

def is_nonlinear_step(R_i_e_current, R_i_e_prev, e_current, e_prev):
    return (R_i_e_current - R_i_e_prev) > (e_current - e_prev)

def find_next_e_y(task_i, e_prev, R_i_e_prev, task_set, policy):
    e_current = e_prev + 1 # Start searching from the next integer exceedance
    while True:
        R_i_e_current = calculate_R_i_e(task_i, e_current, task_set, policy)
        if is_nonlinear_step(R_i_e_current, R_i_e_prev, e_current, e_prev):
            return e_current, R_i_e_current
        e_current += 1
        # Add a safeguard for infinite loop if no more nonlinearities or system becomes unschedulable
        if e_current > MAX_EXCEEDANCE_TO_CHECK:
            return None, None
